function hIndex(citations) {
  const c = [...citations].sort((a, b) => b - a);   // most cited first
  let h = 0;
  while (h < c.length && c[h] >= h + 1) h++;        // the (h+1)-th best paper has at least h+1 citations
  return h;
}

int hIndex(int[] citations) {
    int[] c = citations.clone();
    Arrays.sort(c);                                   // ascending: read it from the end
    int n = c.length, h = 0;
    while (h < n && c[n - 1 - h] >= h + 1) h++;       // the (h+1)-th best paper has at least h+1 citations
    return h;
}

int hIndex(vector<int>& citations) {
    vector<int> c = citations;
    sort(c.begin(), c.end(), greater<int>());         // most cited first
    int h = 0;
    while (h < (int)c.size() && c[h] >= h + 1) h++;   // the (h+1)-th best paper has at least h+1 citations
    return h;
}

function hIndex(citations) {
  const n = citations.length;
  const count = new Array(n + 1).fill(0);
  for (const c of citations) count[Math.min(c, n)]++;   // more than n citations counts as n
  let papers = 0;
  for (let h = n; h > 0; h--) {
    papers += count[h];                                 // papers with at least h citations
    if (papers >= h) return h;
  }
  return 0;
}

def h_index(citations):
    n = len(citations)
    count = [0] * (n + 1)
    for c in citations:
        count[min(c, n)] += 1             # more than n citations counts as n
    papers = 0
    for h in range(n, 0, -1):
        papers += count[h]                # papers with at least h citations
        if papers >= h:
            return h
    return 0

